CREATE OR REPLACE FUNCTION public.home_activity() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in first'; END IF; RETURN jsonb_build_object('posted',(SELECT coalesce(jsonb_agg(x),'[]') FROM (SELECT i.id, array_agg(ic.circle_id) circle_ids FROM public.items i JOIN public.item_circles ic ON ic.item_id=i.id WHERE public.is_member(ic.circle_id) AND i.created_at>=date_trunc('month',now() AT TIME ZONE 'America/Los_Angeles') AT TIME ZONE 'America/Los_Angeles' GROUP BY i.id) x),'completed',(SELECT coalesce(jsonb_agg(x),'[]') FROM (SELECT i.id,max(cl.picked_up_at) picked_up_at,array_agg(DISTINCT ic.circle_id) circle_ids FROM public.items i JOIN public.claims cl ON cl.item_id=i.id JOIN public.item_circles ic ON ic.item_id=i.id WHERE public.is_member(ic.circle_id) AND cl.status IN('picked_up','thanked') GROUP BY i.id ORDER BY max(cl.picked_up_at) DESC) x),'members',(SELECT coalesce(jsonb_agg(x),'[]') FROM (SELECT cm.user_id,array_agg(cm.circle_id) circle_ids FROM public.circle_members cm WHERE cm.status='active' AND public.is_member(cm.circle_id) GROUP BY cm.user_id) x)); END $$;
REVOKE ALL ON FUNCTION public.home_activity() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.home_activity() TO authenticated;
CREATE OR REPLACE FUNCTION public.admin_reply_metrics() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_admin() THEN RAISE EXCEPTION 'Admin access required'; END IF; RETURN (SELECT coalesce(jsonb_agg(x),'[]') FROM (SELECT date_trunc('week',cl.created_at)::date week, count(*) claims,round(100.0*count(*) FILTER(WHERE EXISTS(SELECT 1 FROM public.messages m WHERE m.claim_id=cl.id AND m.sender_id=i.giver_id AND m.created_at>=cl.created_at AND m.created_at<=cl.created_at+interval '24 hours'))/nullif(count(*),0),1) replied_within_24h FROM public.claims cl JOIN public.items i ON i.id=cl.item_id WHERE NOT EXISTS(SELECT 1 FROM public.item_circles ic JOIN public.circles c ON c.id=ic.circle_id WHERE ic.item_id=i.id AND c.is_test) AND cl.created_at<=now()-interval '24 hours' GROUP BY 1 ORDER BY 1 DESC) x); END $$;
REVOKE ALL ON FUNCTION public.admin_reply_metrics() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.admin_reply_metrics() TO authenticated;